package br.com.lealinfo.vidraceiro;
import android.app.*;import android.content.*;import android.content.res.ColorStateList;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import java.util.*;
/** Presentation only. Original controls, hierarchy, listeners and data remain owned by MainActivity. */
final class InteriorVisuals {
 static final int INK=0xff03101f,WHITE=0xffe5f4fb,MUTED=0xffacc4d6,CYAN=0xff26c8f4,PURPLE=0xffa184ff,GOLD=0xffffbc48,GREEN=0xff24d7aa;
 static int dp(Context c,float x){return Math.round(x*c.getResources().getDisplayMetrics().density);}
 static int[] accents={GREEN,PURPLE,CYAN,GOLD,0xff8a91ff,0xff38cddb,GOLD,0xff80b9ed,0xffeb6d91,GREEN,CYAN,PURPLE};
 static GradientDrawable surface(Context c,int color,boolean focus){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{color,0xff041322});d.setCornerRadius(dp(c,10));d.setStroke(dp(c,focus?2:1),focus?CYAN:0xff28607d);return d;}
 static Drawable field(Context c){StateListDrawable d=new StateListDrawable();d.addState(new int[]{-android.R.attr.state_enabled},surface(c,0xff111c29,false));d.addState(new int[]{android.R.attr.state_focused},surface(c,0xff11435a,true));d.addState(new int[]{},surface(c,0xff071e30,false));return d;}
 static Drawable action(Context c,boolean destructive,boolean primary){int color=destructive?0xffbb5771:primary?CYAN:0xff4588ab;StateListDrawable s=new StateListDrawable();s.addState(new int[]{android.R.attr.state_pressed},new Panel(c,color,-1,true));s.addState(new int[]{},new Panel(c,color,-1,primary));return new RippleDrawable(ColorStateList.valueOf(0x4435cfff),s,null);}
 static int index(String p,String h){if(p.startsWith("cut"))return 9;if(p.equals("drawing"))return 10;if(p.equals("budget"))return 0;if(p.equals("contract"))return 4;if(p.equals("tempera"))return 3;if(p.toLowerCase(Locale.ROOT).contains("aterial"))return 8;if(p.equals("calculator"))return 6;if(h.contains("Forneced"))return 7;if(h.contains("Financeiro"))return 5;if(h.contains("Estoque"))return 11;if(p.contains("contact"))return 1;return 2;}
 static String subtitle(String p){switch(p){case "project":return "Crie e gerencie seus projetos";case "projects":return "Seu trabalho, pronto para continuar";case "contacts":case "contact":return "Pessoas e vínculos do seu trabalho";case "budget":return "Valores e documentos do projeto";case "contract":return "Textos e revisões preservadas";case "drawing":return "Medidas reais • representação geométrica";case "cut":case "cutPiece":case "cutResult":return "Chapas, peças e aproveitamento";case "photo":return "Referência real do local";case "tempera":return "Especificações do profissional";case "calculator":return "Medidas, área e perímetro";case "materials":case "material":case "projectMaterials":return "Materiais do seu trabalho";default:return "Seu projeto, organizado";}}
 static void header(MainActivity a,String page,String heading,Button back){int idx=index(page,heading);Workspace workspace=(Workspace)a.root;workspace.module=idx;
 LinearLayout signature=new LinearLayout(a);signature.setGravity(Gravity.CENTER_VERTICAL);signature.setPadding(0,0,0,a.px(10));back.setTag("interior-back");back.setTextSize(12);signature.addView(back,new LinearLayout.LayoutParams(a.px(98),a.px(48)));signature.addView(new View(a),new LinearLayout.LayoutParams(0,1,1));ImageView av=new ImageView(a);av.setImageResource(R.drawable.brand_foreground);signature.addView(av,new LinearLayout.LayoutParams(a.px(34),a.px(34)));LinearLayout words=new LinearLayout(a);words.setOrientation(1);words.setPadding(a.px(4),0,a.px(2),0);TextView angra=new TextView(a);angra.setText("ANGRA");angra.setTextSize(14);angra.setTextColor(WHITE);angra.setTypeface(null,Typeface.BOLD);words.addView(angra);TextView vidros=new TextView(a);vidros.setText("V I D R O S");vidros.setTextSize(8);vidros.setTextColor(CYAN);words.addView(vidros);signature.addView(words);a.root.addView(signature);
 LinearLayout title=new LinearLayout(a);title.setGravity(Gravity.CENTER_VERTICAL);title.setPadding(a.px(14),a.px(18),a.px(18),a.px(18));title.setMinimumHeight(a.px(108));title.setBackground(new Panel(a,accents[idx],idx,false));HomeVisuals.Icon icon=new HomeVisuals.Icon(a,idx);title.addView(icon,new LinearLayout.LayoutParams(a.px(34),a.px(38)));LinearLayout copy=new LinearLayout(a);copy.setOrientation(1);copy.setPadding(a.px(12),0,0,0);TextView name=new TextView(a);name.setText(heading);name.setTag("interior-heading");name.setTextSize(20);name.setTypeface(null,Typeface.BOLD);name.setTextColor(WHITE);copy.addView(name);TextView sub=new TextView(a);sub.setText(subtitle(page));sub.setTextSize(12);sub.setTextColor(0xffb6d6e6);sub.setPadding(0,a.px(5),0,0);copy.addView(sub);title.addView(copy,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=a.px(12);a.root.addView(title,lp);}
 /** Draws native section surfaces under the existing controls, never over them or as click targets. */
 static final class Workspace extends LinearLayout {
 final ArrayList<Group> groups=new ArrayList<>();final Paint paint=new Paint(3);int module=2;Workspace(Context c){super(c);HomeVisuals.images(c);}
 @Override protected void dispatchDraw(Canvas canvas){float w=getWidth(),h=dp(getContext(),210);canvas.save();canvas.clipRect(0,0,w,h);paint.setAlpha(55);canvas.drawBitmap(HomeVisuals.facadeImage,null,new RectF(w*.24f,0,w,h),paint);paint.setAlpha(255);paint.setShader(new LinearGradient(0,0,0,h,new int[]{0x0003101f,INK},null,Shader.TileMode.CLAMP));canvas.drawRect(0,0,w,h,paint);paint.setShader(null);canvas.restore();for(Group g:groups){if(g.first.getParent()!=this||g.last.getParent()!=this)continue;g.panel.setBounds(getPaddingLeft(),g.first.getTop()-dp(getContext(),9),getWidth()-getPaddingRight(),g.last.getBottom()+dp(getContext(),10));g.panel.draw(canvas);}super.dispatchDraw(canvas);}
 }
 static final class Group{final View first,last;final Panel panel;Group(Context c,View f,View l,int color){first=f;last=l;panel=new Panel(c,color,-1,false);}}
 static String label(View v){return v instanceof TextView?((TextView)v).getText().toString():"";}
 static void margins(View v,int left,int top,int right,int bottom){if(!(v.getLayoutParams() instanceof LinearLayout.LayoutParams))return;LinearLayout.LayoutParams p=(LinearLayout.LayoutParams)v.getLayoutParams();p.setMargins(left,top,right,bottom);v.setLayoutParams(p);}
 static void group(Workspace w,int start,int end,int color,int glyph){Context c=w.getContext();View first=w.getChildAt(start),last=w.getChildAt(end);w.groups.add(new Group(c,first,last,color));for(int k=start;k<=end;k++){View child=w.getChildAt(k);margins(child,dp(c,12),k==start?dp(c,16):dp(c,5),dp(c,12),k==end?dp(c,22):0);}if(first instanceof TextView&&!(first instanceof EditText)){TextView t=(TextView)first;t.setBackground(null);t.setTextColor(WHITE);t.setTypeface(null,Typeface.BOLD);t.setTextSize(14);t.setPadding(0,dp(c,3),0,dp(c,4));t.setCompoundDrawablePadding(dp(c,9));t.setCompoundDrawablesWithIntrinsicBounds(new Glyph(c,glyph),null,null,null);}}
 static void arrange(Workspace w){w.groups.clear();for(int i=2;i<w.getChildCount();i++){View v=w.getChildAt(i);String s=label(v);int end=i,color=CYAN,glyph=4;
 if(s.startsWith("CLIENTE ")){end=Math.min(i+1,w.getChildCount()-1);color=GOLD;glyph=1;}
 else if(s.equals("Foto do local")){color=PURPLE;glyph=12;while(end+1<w.getChildCount()&&!label(w.getChildAt(end+1)).equals("Medidas reais"))end++;}
 else if(s.equals("Medidas reais")){glyph=13;while(end+1<w.getChildCount()){end++;if(label(w.getChildAt(end)).startsWith("+ ADICIONAR DIMENSÃO"))break;}}
 else if(!(v instanceof EditText)&&v instanceof TextView&&!(v instanceof Button)&&i+1<w.getChildCount()&&w.getChildAt(i+1) instanceof EditText){end=i+1;if(end+1<w.getChildCount()&&w.getChildAt(end+1) instanceof Spinner)end++;glyph=s.contains("Tipo")?14:s.contains("Modelo")?10:s.contains("Observa")?4:s.contains("Telefone")?1:s.contains("Valor")||s.contains("R$")?0:s.contains("Largura")||s.contains("Altura")?13:4;color=s.contains("Modelo")?PURPLE:CYAN;}
 else continue;
 group(w,i,end,color,glyph);i=end;}w.invalidate();}
 static void install(MainActivity a,LinearLayout target){IdentityHashMap<View,Boolean> seen=new IdentityHashMap<>();final int[] count={-1};target.getViewTreeObserver().addOnGlobalLayoutListener(()->{if(a.root==target&&!a.page.equals("home")){decorate(a,target,seen,false);if(count[0]!=target.getChildCount()){count[0]=target.getChildCount();arrange((Workspace)target);}}});}
 static void decorate(Context c,View v,IdentityHashMap<View,Boolean> seen,boolean dialog){if(!seen.containsKey(v)){seen.put(v,true);
 if(v instanceof EditText){EditText e=(EditText)v;e.setBackground(field(c));e.setTextColor(WHITE);e.setHintTextColor(MUTED);e.setHighlightColor(0x6631c9ee);e.setPadding(dp(c,12),dp(c,12),dp(c,12),dp(c,12));e.setMinHeight(dp(c,50));if(e.getHint()==null&&e.getContentDescription()!=null)e.setHint(e.getContentDescription());if(e instanceof AutoCompleteTextView){e.setHint("Selecione ou informe o serviço");((AutoCompleteTextView)e).setDropDownBackgroundDrawable(surface(c,0xff102538,false));}}
 else if(v instanceof CheckBox){CheckBox b=(CheckBox)v;b.setTextColor(WHITE);b.setButtonTintList(new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{CYAN,MUTED}));b.setMinHeight(dp(c,48));b.setPadding(dp(c,8),dp(c,8),dp(c,8),dp(c,8));b.setBackground(new Panel(c,0xff316777,-1,false));}
 else if(v instanceof Button){Button b=(Button)v;String label=b.getText().toString().toUpperCase(Locale.ROOT);boolean danger=label.startsWith("EXCLUIR")||label.startsWith("REMOVER");boolean primary=label.startsWith("SALVAR")||label.startsWith("CALCULAR")||label.startsWith("RECALCULAR")||label.startsWith("+");b.setBackground(action(c,danger,primary));if(label.startsWith("CALCULAR")||label.startsWith("RECALCULAR"))b.setBackground(new RippleDrawable(ColorStateList.valueOf(0x4424d7aa),new Panel(c,GREEN,-1,true),null));b.setTextColor(WHITE);b.setTextSize(dialog?12:13);b.setMinHeight(dp(c,dialog?48:54));b.setPadding(dp(c,dialog?8:12),dp(c,10),dp(c,dialog?8:12),dp(c,10));b.setElevation(dp(c,2));if(!dialog){int glyph=label.contains("CLIENTE")?1:label.contains("FOTO")?12:label.contains("3D")?10:label.contains("CÁLC")||label.contains("CALCULAR")?6:label.contains("SALVAR")?15:label.contains("MATERIA")?8:label.contains("CORTE")?9:label.contains("CONTRATO")?4:label.contains("TÊMPERA")?3:-1;if(glyph>=0){b.setCompoundDrawablePadding(dp(c,8));b.setCompoundDrawablesWithIntrinsicBounds(new Glyph(c,glyph),null,null,null);}if(label.contains("\n")||label.contains(" • ")){b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setBackground(new Panel(c,0xff3c91be,-1,false));String raw=b.getText().toString();int split=raw.indexOf('\n');if(split<0)split=raw.indexOf(" • ");if(split>0){android.text.SpannableString styled=new android.text.SpannableString(raw);styled.setSpan(new android.text.style.StyleSpan(Typeface.BOLD),0,split,0);b.setText(styled);}}}else b.setMinWidth(0);}
 else if(v instanceof Spinner){Spinner s=(Spinner)v;s.setBackground(field(c));s.setMinimumHeight(dp(c,48));s.setPopupBackgroundDrawable(surface(c,0xff112a40,false));s.setPadding(dp(c,6),0,dp(c,6),0);if(s.getParent() instanceof LinearLayout&&((LinearLayout)s.getParent()).getOrientation()==LinearLayout.HORIZONTAL&&s.getLayoutParams().width>0){LinearLayout.LayoutParams p=(LinearLayout.LayoutParams)s.getLayoutParams();p.width=dp(c,88);p.leftMargin=dp(c,8);s.setLayoutParams(p);}}
 else if(v instanceof TextView){TextView t=(TextView)v;if(dialog){t.setTextColor(WHITE);t.setLineSpacing(dp(c,2),1);}else if(!"interior-heading".equals(t.getTag())&&t.getTextSize()/c.getResources().getDisplayMetrics().scaledDensity>=18){t.setBackground(new Panel(c,CYAN,-1,false));t.setPadding(dp(c,12),dp(c,14),dp(c,12),dp(c,14));}else if(label(v).equals("DIMENSÃO")||label(v).startsWith("VALOR  •")){t.setTextSize(11);t.setPadding(0,dp(c,6),0,dp(c,6));}else if(label(v).startsWith("Nenhuma foto vinculada")){t.setMinHeight(dp(c,82));t.setGravity(Gravity.CENTER_VERTICAL);t.setCompoundDrawablesWithIntrinsicBounds(new Glyph(c,12),null,null,null);t.setCompoundDrawablePadding(dp(c,12));}}
 else if(v instanceof LinearLayout&&v.getBackground() instanceof GradientDrawable){v.setBackground(new Panel(c,0xff377590,-1,false));}
 }
 if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)decorate(c,g.getChildAt(i),seen,dialog);}}
 /** Glass depth, edge lighting and the exact same module atlas as Home. No interface bitmap. */
 static final class Panel extends Drawable{final Paint p=new Paint(3);final int accent,module;final float d;final boolean strong;Panel(Context c,int a,int m,boolean s){HomeVisuals.images(c);accent=a;module=m;strong=s;d=c.getResources().getDisplayMetrics().density;}
 public void draw(Canvas c){Rect b=getBounds();float w=b.width(),h=b.height(),r=14*d;c.save();c.translate(b.left,b.top);Path clip=new Path();clip.addRoundRect(new RectF(0,0,w,h),r,r,Path.Direction.CW);c.clipPath(clip);int mid=Color.rgb(Color.red(accent)/(strong?2:5),Color.green(accent)/(strong?2:5),Color.blue(accent)/(strong?2:5));p.setShader(new LinearGradient(0,0,w,h,new int[]{mid,0xff072037,0xff041322},null,Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,p);p.setShader(new RadialGradient(0,h*.2f,Math.max(w,h)*.8f,new int[]{(accent&0xffffff)|0x48000000,0x00000000},null,Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,p);p.setShader(null);
 if(module>=0){int cell=HomeVisuals.moduleImage.getWidth()/4;Rect src=new Rect(module%4*cell,module/4*cell,(module%4+1)*cell,(module/4+1)*cell);float size=Math.min(h*1.12f,w*.5f);p.setAlpha(85);c.drawBitmap(HomeVisuals.moduleImage,src,new RectF(w-size+9*d,0,w+9*d,size),p);p.setAlpha(255);}
 Path sheen=new Path();sheen.moveTo(w*.63f,0);sheen.lineTo(w*.79f,0);sheen.lineTo(w*.46f,h);sheen.lineTo(w*.38f,h);sheen.close();p.setShader(new LinearGradient(0,0,w,h,new int[]{0x0d9cecff,0x008ae5ff},null,Shader.TileMode.CLAMP));c.drawPath(sheen,p);p.setShader(null);p.setColor((accent&0xffffff)|0xe0000000);c.drawRoundRect(new RectF(0,8*d,2.5f*d,h-8*d),2*d,2*d,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(5*d);p.setColor((accent&0xffffff)|0x18000000);c.drawRoundRect(new RectF(d,d,w-d,h-d),r,r,p);p.setStrokeWidth(1.2f*d);p.setColor((accent&0xffffff)|0x9a000000);c.drawRoundRect(new RectF(d,d,w-d,h-d),r,r,p);p.setStrokeWidth(.6f*d);p.setColor(0x4482dcff);c.drawLine(13*d,2*d,w-13*d,2*d,p);p.setStyle(Paint.Style.FILL);c.restore();}
 public void setAlpha(int a){}public void setColorFilter(ColorFilter f){}public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
 static final class Glyph extends Drawable{final Paint p=new Paint(3);final Context c;final int kind;Glyph(Context c,int k){this.c=c;kind=k;setBounds(0,0,dp(c,24),dp(c,26));}public int getIntrinsicWidth(){return dp(c,24);}public int getIntrinsicHeight(){return dp(c,26);}public void draw(Canvas out){Rect b=getBounds();out.save();out.translate(b.left,b.top);out.scale(b.width()/48f,b.height()/48f);p.setColor(0xffbceeff);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setStrokeJoin(Paint.Join.ROUND);p.setStrokeCap(Paint.Cap.ROUND);
 if(kind==12){out.drawRoundRect(4,13,44,40,4,4,p);out.drawCircle(24,26,9,p);out.drawLine(14,13,18,7,p);out.drawLine(18,7,30,7,p);out.drawLine(30,7,34,13,p);}else if(kind==13){out.rotate(-40,24,24);out.drawRoundRect(6,15,42,33,2,2,p);for(int x=12;x<39;x+=7)out.drawLine(x,15,x,22,p);}else if(kind==14){for(int y=10;y<=38;y+=13){out.drawCircle(7,y,1,p);out.drawLine(16,y,42,y,p);}}else if(kind==15){out.drawRoundRect(6,5,42,43,2,2,p);out.drawRect(15,5,34,19,p);out.drawRect(13,27,35,43,p);}else{out.save();out.scale(1,1);HomeVisuals.Icon icon=new HomeVisuals.Icon(c,kind);icon.layout(0,0,48,48);icon.draw(out);out.restore();}out.restore();}public void setAlpha(int a){}public void setColorFilter(ColorFilter f){}public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
 static final class Dialog extends AlertDialog.Builder {final Context c;Dialog(Context c){super(c);this.c=c;}@Override public AlertDialog show(){AlertDialog d=super.show();Window w=d.getWindow();if(w!=null){w.setBackgroundDrawable(new Panel(c,CYAN,-1,false));View root=w.getDecorView();IdentityHashMap<View,Boolean> seen=new IdentityHashMap<>();root.getViewTreeObserver().addOnGlobalLayoutListener(()->decorate(c,root,seen,true));decorate(c,root,seen,true);}return d;}}
}
